import React, { useState } from 'react';

export default function GeneratedScreen() {
  const [isOpen, setIsOpen] = useState(true);
  const [statusMessage, setStatusMessage] = useState('');
  const [isRetrying, setIsRetrying] = useState(false);

  const handleRetry = () => {
    setIsRetrying(true);
    setStatusMessage('Checking port 8090 availability...');
    setTimeout(() => {
      setIsRetrying(false);
      setStatusMessage('Port 8090 is still occupied by PID 14202 (node.exe).');
    }, 1200);
  };

  const handleCancel = () => {
    setIsOpen(false);
  };

  if (!isOpen) {
    return (
      <div className="w-screen h-screen bg-slate-100 flex items-center justify-center font-sans">
        <div className="text-center">
          <p className="text-slate-600 mb-4">Application dialog closed.</p>
          <button 
            onClick={() => { setIsOpen(true); setStatusMessage(''); }}
            className="px-4 py-2 bg-blue-600 text-white rounded shadow hover:bg-blue-700 text-sm font-medium transition-colors"
          >
            Reopen Warning Dialog
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="w-screen h-screen bg-[#cccccc] flex items-center justify-center font-sans select-none overflow-hidden relative">

      {/* Background Mock Desktop Window / Environment */}
      <div className="absolute inset-0 bg-gradient-to-br from-blue-800 to-indigo-900 flex flex-col opacity-40">
        <div className="h-10 bg-slate-900 flex items-center px-4 space-x-2 border-b border-slate-700">
          <div className="w-3 h-3 rounded-full bg-red-500"></div>
          <div className="w-3 h-3 rounded-full bg-yellow-500"></div>
          <div className="w-3 h-3 rounded-full bg-green-500"></div>
          <span className="text-slate-400 text-xs ml-4">Server Manager - v2.4.1 (Running)</span>
        </div>
        <div className="flex-1 p-6 text-white text-sm">
          <p className="opacity-75">Initializing background services...</p>
          <p className="opacity-50 mt-2">Listening on interfaces: 127.0.0.1, ::1</p>
          {statusMessage && (
            <div className="mt-6 p-3 bg-black/40 border border-amber-500/50 rounded text-amber-300 max-w-md">
              <span className="font-semibold">System log:</span> {statusMessage}
            </div>
          )}
        </div>
      </div>

      {/* Win32 Desktop Modal Dialog */}
      <div className="relative w-[520px] bg-[#f0f0f0] border border-[#707070] shadow-2xl flex flex-col">

        {/* Win32 TitleBar */}
        <div className="h-8 bg-[#1c1c1c] text-[#f0f0f0] flex items-center justify-between px-3 select-none">
          <div className="flex items-center space-x-2">
            <svg className="w-4 h-4 text-amber-500" viewBox="0 0 16 16" fill="currentColor">
              <path d="M8 1L1 14h14L8 1zm0 3.5l4.5 8H3.5L8 4.5zM7.25 7v3h1.5V7h-1.5zm0 4v1.5h1.5V11h-1.5z"/>
            </svg>
            <span className="text-xs tracking-wide">Warning</span>
          </div>
          <div className="flex items-center">
            {/* Minimize */}
            <button className="w-10 h-7 flex items-center justify-center hover:bg-[#333333] text-white">
              <svg className="w-3 h-3" viewBox="0 0 10 10" fill="none" stroke="currentColor">
                <path d="M1 5h8" strokeWidth="1"/>
              </svg>
            </button>
            {/* Maximize (disabled look) */}
            <button className="w-10 h-7 flex items-center justify-center hover:bg-[#333333] text-white opacity-50 cursor-default">
              <svg className="w-3 h-3" viewBox="0 0 10 10" fill="none" stroke="currentColor">
                <rect x="1.5" y="1.5" width="7" height="7" strokeWidth="1"/>
              </svg>
            </button>
            {/* Close */}
            <button 
              onClick={handleCancel}
              className="w-10 h-7 flex items-center justify-center hover:bg-[#e81123] text-white transition-colors"
            >
              <svg className="w-3 h-3" viewBox="0 0 10 10" fill="none" stroke="currentColor">
                <path d="M1 1l8 8M9 1L1 9" strokeWidth="1"/>
              </svg>
            </button>
          </div>
        </div>

        {/* Content Area */}
        <div className="p-6 flex flex-col justify-between flex-1 bg-[#f0f0f0]">
          <div className="flex items-start space-x-4">
            {/* Warning Icon */}
            <div className="flex-shrink-0 pt-1">
              <svg className="w-9 h-9 text-[#d97706]" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75">
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126zM12 15.75h.007v.008H12v-.008z" />
              </svg>
            </div>

            {/* Message Body */}
            <div className="text-[13px] leading-relaxed text-[#1e1e1e] font-normal">
              It appears that port <span className="font-semibold">8090</span> is already in use. Please exit the application that uses that port, or change the port number for this application in the <span className="font-semibold">Server</span> tab of the <span className="font-semibold">App Settings</span> dialog.

              {statusMessage && (
                <div className="mt-3 text-xs text-red-600 font-medium">
                  {statusMessage}
                </div>
              )}
            </div>
          </div>

          {/* Button Group */}
          <div className="mt-8 flex items-center justify-end space-x-3">
            {/* Retry Button with Win32 Focus Dotted Border */}
            <button
              onClick={handleRetry}
              disabled={isRetrying}
              className="relative px-6 py-1.5 bg-[#e1e1e1] hover:bg-[#e5f1fb] active:bg-[#cce4f7] text-[#1e1e1e] text-xs font-normal border border-[#adadad] hover:border-[#0078d4] active:border-[#005499] shadow-sm focus:outline-none transition-all duration-75 disabled:opacity-50"
            >
              {/* Win32 programmatic focus indicator ring */}
              <span className="absolute inset-[2px] border border-dashed border-[#666666] pointer-events-none"></span>
              {isRetrying ? 'Retrying...' : 'Retry'}
            </button>

            {/* Cancel Button */}
            <button
              onClick={handleCancel}
              className="px-6 py-1.5 bg-[#e1e1e1] hover:bg-[#e5f1fb] active:bg-[#cce4f7] text-[#1e1e1e] text-xs font-normal border border-[#adadad] hover:border-[#0078d4] active:border-[#005499] shadow-sm focus:outline-none transition-all duration-75"
            >
              Cancel
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

