import React, { useState } from 'react';

export default function GeneratedScreen() {
  const [activeTab, setActiveTab] = useState('Results');
  const [zoomLevel, setZoomLevel] = useState('100 %');
  const [selectedCell, setSelectedCell] = useState({ row: 0, col: 'name' });
  const [copiedToast, setCopiedToast] = useState(false);

  const queryResults = [
    { id: 1, name: 'rjain', type_desc: 'SQL_LOGIN', is_disabled: 0 },
    { id: 2, name: 'sa', type_desc: 'SQL_LOGIN', is_disabled: 1 },
    { id: 3, name: 'app_service_user', type_desc: 'SQL_LOGIN', is_disabled: 0 },
    { id: 4, name: 'reporting_ro', type_desc: 'SQL_LOGIN', is_disabled: 0 }
  ];

  const queryMessages = [
    { id: 1, type: 'info', text: 'Command(s) completed successfully.', time: '14:32:01' },
    { id: 2, type: 'info', text: '(1 row(s) affected)', time: '14:32:01' }
  ];

  const handleCellClick = (rowIdx, colKey, val) => {
    setSelectedCell({ row: rowIdx, col: colKey });
    navigator.clipboard?.writeText(String(val));
    setCopiedToast(true);
    setTimeout(() => setCopiedToast(false), 2000);
  };

  return (
    <div className="flex flex-col h-screen w-screen bg-white font-mono text-xs select-none overflow-hidden text-gray-900">

