      dateDivider: 'Friday'
    },
    {
      id: 4,
      sender: 'Me',
      avatar: 'ME',
      timestamp: 'Friday 11:52',
      content: 'received id card',
      isMe: true,
      dateDivider: null
    },
    {
      id: 5,
      sender: 'Gandhar, Chougule - SCHAEFFLER',
      avatar: 'CG',
      timestamp: 'Friday 12:06',
      content: 'Very good',
      isMe: false,
      dateDivider: null
    }
  ]);
  const [inputText, setInputText] = useState('');
  const [toastMessage, setToastMessage] = useState('');

  const showToast = (msg) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(''), 3000);
  };

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (!inputText.trim()) return;

    const newMessage = {
      id: messages.length + 1,
      sender: 'Me',
      avatar: 'ME',
      timestamp: 'Today 14:30',
      content: inputText,
      isMe: true,
      dateDivider: null
    };

    setMessages([...messages, newMessage]);
    setInputText('');
    showToast('Message sent');
  };

  return (
    <div className="flex flex-col h-screen w-screen bg-[#F3F2F1] font-['Segoe_UI',-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif] text-[#242424] overflow-hidden select-none">

      {/* Toast Notification */}
      {toastMessage && (
        <div className="absolute top-16 right-6 z-50 bg-[#242424] text-white px-4 py-2 rounded shadow-lg text-xs flex items-center space-x-2 animate-fade-in">
          <svg className="w-4 h-4 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7" />
          </svg>
          <span>{toastMessage}</span>
        </div>
      )}

      {/* Top Navigation Bar */}
      <header className="h-12 bg-white border-b border-[#E1DFDD] flex items-center justify-between px-4 shrink-0">

        {/* Left Header info */}
        <div className="flex items-center space-x-3 overflow-hidden">
          <div className="relative flex items-center justify-center w-8 h-8 rounded-full bg-[#E1DFDD] text-[#6264A7] font-semibold text-xs shrink-0">
            CG
            <span className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 border-2 border-white rounded-full"></span>
          </div>
          <span className="font-semibold text-sm truncate text-[#242424]">
            Gandhar, Chougule - SCHAEFFLER
          </span>

          {/* Nav Tabs */}
          <nav className="flex items-center space-x-1 ml-6 text-sm">
            {['Chat', 'Shared', 'Recap', 'Storyline'].map((tab) => (
              <button
                key={tab}
                onClick={() => {
                  setActiveTab(tab);
                  showToast(`Switched to ${tab} tab`);
                }}
                className={`px-3 py-1.5 rounded relative transition-colors ${
                  activeTab === tab
                    ? 'text-[#6264A7] font-semibold'
                    : 'text-[#616161] hover:bg-[#F3F2F1]'
