import React, { useState, useRef, useEffect } from 'react';

export default function GeneratedScreen() {
  const [messages, setMessages] = useState([
    {
      id: 1,
      sender: 'Shivangi Shah',
      isMe: false,
      timestamp: 'Oct 2, 12:00 PM',
      content: 'with sdet.\n\ntry to do some AI certifications copilot gh300 its quite easy, gemini agent development and if possible go for claude its value addon and nowadays everyone is looking for AI certifications. invest your time in AI. alongside you can also start practicing leet code problems begin with easy ones that itself builds good confidence and try to prepare one framework on your own covering all the practical usecases. and nowadays interviews are more focused on scenario based. try to utilise AI for your interview preparation.'
    },
    {
      id: 2,
      sender: 'Me',
      isMe: true,
      timestamp: 'Oct 2, 12:01 PM',
      content: 'whats tools and technologies are you working on ?'
    },
    {
      id: 3,
      sender: 'Shivangi Shah',
      isMe: false,
      timestamp: 'Oct 2, 12:04 PM',
      content: 'Playwright is in demand as compared to selenium as it has mcp capability. also it has more opening and less competition.'
    }
  ]);

  const [inputText, setInputText] = useState('');
  const messagesEndRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (!inputText.trim()) return;

    const newMessage = {
      id: Date.now(),
      sender: 'Me',
      isMe: true,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      content: inputText.trim()
    };

    setMessages((prev) => [...prev, newMessage]);
    setInputText('');
  };

  return (
    <div className="flex justify-center items-center min-h-screen bg-gray-100 font-sans">
      {/* Mobile Device Frame */}
      <div className="w-full max-w-md h-[100vh] sm:h-[844px] bg-white flex flex-col shadow-2xl sm:rounded-[40px] overflow-hidden relative border border-gray-200">

        {/* iOS Status Bar */}
        <div className="h-12 bg-white flex justify-between items-center px-6 pt-2 select-none z-20">
          <span className="text-black font-semibold text-sm tracking-tight">3:18</span>
          <div className="flex items-center space-x-2">
            {/* Cellular & 5G Icon */}
            <div className="flex items-end space-x-[2px] h-3">
              <span className="w-[3px] h-1.5 bg-black rounded-sm"></span>
              <span className="w-[3px] h-2 bg-black rounded-sm"></span>
              <span className="w-[3px] h-2.5 bg-black rounded-sm"></span>
              <span className="w-[3px] h-3 bg-black rounded-sm"></span>
            </div>
            <span className="text-xs font-bold tracking-tighter">5G</span>
            {/* Battery Icon */}
            <div className="w-6 h-3 border border-black rounded-sm p-[1px] flex items-center">
              <div className="h-full w-full bg-black rounded-[1px]"></div>
            </div>
          </div>
        </div>

        {/* Header Bar */}
        <div className="flex items-center justify-between px-4 py-3 bg-white border-b border-gray-100 z-10 shadow-xs">
          <div className="flex items-center space-x-3">
            <button className="text-[#ff6b4a] focus:outline-none hover:opacity-80 transition-opacity">
              <svg className="w-6 h-6 stroke-[2.5]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" />
              </svg>
            </button>
            <div className="flex items-center space-x-3">
              <div className="relative">
                <div className="w-10 h-10 rounded-full bg-orange-100 flex items-center justify-center overflow-hidden border border-gray-200">
                  {/* Avatar Illustration */}
                  <div className="w-full h-full bg-amber-200 flex items-end justify-center pt-2">
                    <div className="w-7 h-7 bg-amber-400 rounded-t-full relative flex items-center justify-center">
                      {/* Glasses & Hair Mock */}
                      <div className="absolute top-1 w-6 h-2 border border-black rounded-full"></div>
                    </div>
                  </div>
                </div>
                <div className="absolute bottom-0 right-0 w-3 h-3 bg-green-500 rounded-full border-2 border-white"></div>
              </div>
              <div>
                <h1 className="font-semibold text-gray-900 text-base leading-tight">Shivangi Shah</h1>
                <p className="text-xs text-gray-400">Online</p>
              </div>
            </div>
          </div>
          <button className="text-gray-600 focus:outline-none hover:text-gray-900">
            <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24">
              <circle cx="12" cy="6" r="1.5" />
              <circle cx="12" cy="12" r="1.5" />
              <circle cx="12" cy="18" r="1.5" />
            </svg>
          </button>
        </div>

        {/* Message Feed / Stream */}
        <div className="flex-1 overflow-y-auto px-4 py-6 space-y-6 bg-white">
          {messages.map((msg, index) => {
            const showTimestamp = index === 0 || messages[index - 1].timestamp !== msg.timestamp;
            return (
              <React.Fragment key={msg.id}>
                {showTimestamp && (
                  <div className="flex justify-center my-2">
                    <span className="text-[11px] text-gray-400 font-medium tracking-wide">
                      {msg.timestamp}
                    </span>
                  </div>
                )}
                <div className={`flex ${msg.isMe ? 'justify-end' : 'justify-start'}`}>
                  <div
                    className={`max-w-[82%] rounded-2xl px-4 py-3 text-sm leading-relaxed whitespace-pre-wrap shadow-xs ${
                      msg.isMe
                        ? 'bg-[#ff6b4a] text-white rounded-br-xs'
                        : 'bg-[#f2f2f2] text-[#333333] rounded-bl-xs border border-gray-200/60'
                    }`}
                  >
                    {msg.content}
                  </div>
                </div>
              </React.Fragment>
            );
          })}
          <div ref={messagesEndRef} />
        </div>

        {/* Chat Input Bar */}
