import React, { useState, useEffect } from 'react';

export default function GeneratedScreen() {
  // ---------------------------------------------------------------------------
  // 1. PLC TAGS & LIVE STATE SYSTEM (Siemens WinCC / TIA Portal Architecture)
  // ---------------------------------------------------------------------------
  const [plcTags, setPlcTags] = useState({
    Line_Auto_Running: true,
    Operating_Mode: 'AUTO', // 'AUTO' | 'MANUAL'
    Power_ON: true,
    E_Stop_Active: false,
    CycleTimeSeconds: 42.8,
    MB140_BIW_No: 2045,
    ActiveStation: 'MB110-140',
    PLC_Connected: true,
    RFID_Reader_Status: 'OK',
    ActiveAlarmCount: 1,
    ActiveAlarmText: 'LineHighAlarm.Astop.Astop_140LHLC1 : 140LHLoadLC1_Grating fault',
    Zone1_Status: 'RUNNING',
    Zone2_Status: 'WAIT_TAKEOUT',
    StationNodes: [
      { id: 1, status: 'fault' }, { id: 2, status: 'ok' }, { id: 3, status: 'ok' },
      { id: 4, status: 'ok' }, { id: 5, status: 'ok' }, { id: 6, status: 'ok' },
      { id: 7, status: 'ok' }, { id: 8, status: 'fault' }, { id: 9, status: 'fault' },
      { id: 10, status: 'ok' }, { id: 11, status: 'ok' }, { id: 12, status: 'ok' },
      { id: 13, status: 'ok' }, { id: 14, status: 'ok' }, { id: 15, status: 'ok' },
      { id: 16, status: 'ok' }, { id: 17, status: 'ok' }, { id: 18, status: 'ok' },
      { id: 19, status: 'ok' }, { id: 20, status: 'ok' }, { id: 21, status: 'ok' },
      { id: 22, status: 'ok' }, { id: 23, status: 'ok' }, { id: 24, status: 'ok' },
    ]
  });

  // HMI UI Control States
  const [alarmMuted, setAlarmMuted] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(true);
  const [activeNavTab, setActiveNavTab] = useState('Station data Modify');
  const [toastMessage, setToastMessage] = useState(null);
  const [showResetConfirm, setShowResetConfirm] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date().toLocaleString());

  // Form Data State: Manual Pre To Actual (Actual Data)
  const [actualData, setActualData] = useState({
    seqNo: '1042',
    vinNo: 'MA3EWB1100049281',
    variant: 'SUV_X5_PLUS',
    variantCode: '582',
    subVariant: 'FLAT_ROOF_PANORAMIC',
    biwNo: '2045',
    bodyState: 'Normal/Ok',
    takeOutLocation: 'No Action',
    takeInTakeOutReason: 'No Action',
    skidNo: 'SKID-882'
  });

  // Form Data State: Manual Actual To Transfer (Transfer Data)
  const [transferData, setTransferData] = useState({
    seqNo: '0',
    vinNo: '',
    variant: 'Select Variant',
    variantCode: '0',
    subVariant: 'Select Sub-Variant',
    biwNo: '0',
    bodyState: 'Normal/Ok',
    takeOutLocation: 'No Action',
    takeInTakeOutReason: 'No Action',
    skidNo: '0'
  });

  // Dynamic timestamp update loop
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date().toLocaleString('de-DE', {
        day: '2-digit', month: '2-digit', year: 'numeric',
        hour: '2-digit', minute: '2-digit', second: '2-digit'
      }));
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // Toast auto-clear
  const showToast = (msg) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3500);
  };

  // PLC Action Handlers
  const togglePower = () => {
    const nextPower = !plcTags.Power_ON;
    setPlcTags(prev => ({ ...prev, Power_ON: nextPower }));
    showToast(nextPower ? 'PLC System Powered ON' : 'PLC System Powered OFF');
  };

  const setOperatingMode = (mode) => {
    setPlcTags(prev => ({
      ...prev,
      Operating_Mode: mode,
      Line_Auto_Running: mode === 'AUTO'
    }));
    showToast(`Operating Mode switched to ${mode}`);
  };

  const handleMuteAlarm = () => {
    setAlarmMuted(prev => !prev);
    showToast(alarmMuted ? 'Alarm Sound Unmuted' : 'Alarm Sound Muted');
  };

  const handleResetAll = () => {
    setShowResetConfirm(true);
  };

  const confirmResetAll = () => {
    setPlcTags(prev => ({
      ...prev,
      ActiveAlarmCount: 0,
      ActiveAlarmText: 'SYSTEM OK: All station faults cleared',
      E_Stop_Active: false
    }));
    setShowResetConfirm(false);
    showToast('PLC Alarm Buffer Cleared & Reset Signal Transmitted');
  };

  const handleModifySubmit = () => {
    if (!isLoggedIn) {
      showToast('Error: Authentication required to write station data!');
      return;
    }
    showToast(`PLC Tag DB110.Write: Data synchronized for Station ${plcTags.ActiveStation}`);
  };

  const handleEmptySkid = (target) => {
    if (target === 'actual') {
      setActualData(prev => ({ ...prev, skidNo: '0' }));
      showToast('Actual Data: Skid unassigned (SKID = 0)');
    } else {
      setTransferData(prev => ({ ...prev, skidNo: '0' }));
      showToast('Transfer Data: Skid unassigned (SKID = 0)');
    }
  };

  const handleDataDelete = (target) => {
    const emptyForm = {
      seqNo: '0',
      vinNo: '',
      variant: 'Select Variant',
      variantCode: '0',
      subVariant: 'Select Sub-Variant',
      biwNo: '0',
      bodyState: 'Normal/Ok',
      takeOutLocation: 'No Action',
      takeInTakeOutReason: 'No Action',
      skidNo: '0'
    };
    if (target === 'actual') {
      setActualData(emptyForm);
      showToast('Actual Data block cleared');
    } else {
      setTransferData(emptyForm);
      showToast('Transfer Data block cleared');
    }
  };

  // Helper for variant code sync
  const updateVariant = (target, value) => {
    const codes = {
      'SUV_X5_PLUS': '582',
      'SEDAN_M3': '411',
      'EV_CROSSOVER': '920',
      'Select Variant': '0'
    };
    const code = codes[value] || '0';
    if (target === 'actual') {
      setActualData(prev => ({ ...prev, variant: value, variantCode: code }));
    } else {
      setTransferData(prev => ({ ...prev, variant: value, variantCode: code }));
    }
  };

  const navItems = [
    'Type', 'Robot', 'SEW-Drives', 'Alarm', 'ProdData',
    'Diagnostic', 'System', 'Style.View', 'Style.Write',
    'RFID', 'Order Control', 'Zone1Type Overview', 'Zone2Type Overview'
  ];

  return (
    <div className="flex flex-col h-screen w-full bg-[#111923] text-gray-100 font-sans select-none overflow-hidden">

      {/* -------------------------------------------------------------------- */}
      {/* 1. TOP SCADA OPERATIONAL BAR                                         */}
      {/* -------------------------------------------------------------------- */}
      <header className="flex items-stretch bg-[#0c131c] border-b-2 border-[#1e2e3e] h-14 text-sm font-semibold shrink-0">

        {/* Left Operational Buttons */}
        <div className="flex items-center space-x-1 px-2 border-r border-[#1e2e3e]">
          {/* ON/OFF Button */}
          <button
            onClick={togglePower}
            className={`px-3 py-2 rounded font-bold shadow-md transition-colors text-xs uppercase tracking-wider ${
              plcTags.Power_ON 
                ? 'bg-amber-500 hover:bg-amber-400 text-slate-950 border-b-2 border-amber-700' 
                : 'bg-red-700 hover:bg-red-600 text-white'
            }`}
          >
            {plcTags.Power_ON ? 'ON/OFF' : 'POWER OFF'}
          </button>

          {/* START Button */}
