import React, { useState, useEffect } from 'react';

export default function GeneratedScreen() {
  // PLC Dynamic Tag State Engine
  const [plcTags, setPlcTags] = useState({
    Line_Auto_Running: true,
    Operating_Mode: 'AUTO', // 'AUTO' | 'MANUAL' | 'START' | 'STOP'
    Power_ON: true,
    E_Stop_Active: false,
    Alarm_Muted: false,
    Station_ID: 'MB110-140',
    Timestamp: '30.10.2026, 17:44:18',
    SelectedRobot: '140RB01 - Main Body Handler',
    WeldSpotCountSummary: 48,
    G1_Count: 12,
    G2_Count: 14,
    G3_Count: 10,
    G4_Count: 12,
    BypassWeldCount: false,
    RbtFeedbackProgram: 14,
    PlcCmdPrg: 14,
  });

  // Selected Active Navigation Tab
  const [activeNavTab, setActiveNavTab] = useState('Robot');
  const [activeSubTab, setActiveSubTab] = useState('Robot Status');

  // Digital Inputs / Outputs (IO Matrix State)
  const [ioStatus, setIoStatus] = useState({
    InAutoOn: true,
    HomePosition: true,
    SystemReady: true,
    MotorOn: true,
    InCycle: true,
    CycleOn: true,
    OnPath: true,
    ProgNumReq: false,
    TaskOK: true,
    PlcCmdPrgVal: 14,
    Manual: false,
    DryRun: false,
    Stop: false,
    EStop: false,
    Error: false,
    ProcessFault: false,
    WaterOK: true,
    AirOK: true,
    RbtFeedbackVal: 14,
  });

  // Collision Zones 1 to 32 status (true = clear/green, false = blocked/red)
  const [collisionZones, setCollisionZones] = useState(
    Array.from({ length: 32 }, (_, i) => ({
      id: i + 1,
      active: true,
      occupiedBy: i === 7 || i === 14 ? 'RB02' : null,
    }))
  );

  // Segment Status items (1-24)
  const [segments, setSegments] = useState(
    Array.from({ length: 24 }, (_, i) => ({
      id: i + 1,
      out: i < 8,
      finish: i < 6,
    }))
  );

  // Dock & Jig Status
  const [docks, setDocks] = useState([
    { id: 1, rel: true, end: true },
    { id: 2, rel: true, end: false },
    { id: 3, rel: false, end: false },
    { id: 4, rel: true, end: true },
  ]);

  const [jigs, setJigs] = useState([
    { id: 1, active: true },
    { id: 2, active: true },
    { id: 3, active: false },
    { id: 4, active: true },
    { id: 5, active: false },
    { id: 6, active: true },
    { id: 7, active: false },
    { id: 8, active: true },
  ]);

  // Alarms Database State
  const [alarms, setAlarms] = useState([
    { id: 1, type: 'HIGH', code: 'LineHighAlarm.Astop.Astop_140LHLC1', msg: '140LHLC1_Grating fault', active: true },
    { id: 2, type: 'HIGH', code: 'LineHighAlarm.Estop.Estop_Zone2_HMI03', msg: 'Estop_Zone2HMI02Emergency stop', active: true },
    { id: 3, type: 'HIGH', code: 'LineHighAlarm.Estop.Estop_Zone2_HMI02', msg: 'Estop_Zone2HMI01Emergency stop', active: true },
    { id: 4, type: 'HIGH', code: 'LineHighAlarm.Estop.Estop_Zone1_HMI01', msg: 'Estop_Zone1HMI01Emergency stop', active: true },
    { id: 5, type: 'HIGH', code: 'LineHighAlarm.Estop_140APCLH01OP01', msg: 'Estop_140APCLH01OP01Emergency stop', active: true },
    { id: 6, type: 'HIGH', code: 'LineHighAlarm.Astop.Astop_120ExitLC1', msg: '120ExitLC1_Grating fault', active: true },
    { id: 7, type: 'HIGH', code: 'LineHighAlarm.Astop.Astop_140ExitLC1', msg: '140ExitLC1_Grating fault', active: true },
    { id: 8, type: 'HIGH', code: 'LineHighAlarm.Astop.Astop_130EntryLC1', msg: '140EntryLC1_Grating fault', active: true },
    { id: 9, type: 'INFO', code: 'Inst55.140NC03_DB.instPLP', msg: 'Hide all alarm', active: false },
    { id: 10, type: 'INFO', code: 'Inst53.140NC01.instPLP', msg: 'Hide all alarm', active: false },
    { id: 11, type: 'INFO', code: 'Inst54.140NC02_DB.instPLP', msg: 'Hide all alarm', active: false },
    { id: 12, type: 'INFO', code: 'Inst51.140RB01.instRobotKuka', msg: 'Hide all alarm', active: false },
    { id: 13, type: 'INFO', code: 'Inst52.140RB02.instRobotKuka', msg: 'Hide all alarm', active: false },
  ]);

  // Simulated Clock
  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      setPlcTags((prev) => ({
        ...prev,
        Timestamp: `${now.getDate().toString().padStart(2, '0')}.${(now.getMonth() + 1)
          .toString()
          .padStart(2, '0')}.${now.getFullYear()}, ${now.toLocaleTimeString()}`,
      }));
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // Handlers for Control Actions
  const handlePowerToggle = () => {
    setPlcTags((prev) => ({ ...prev, Power_ON: !prev.Power_ON }));
  };

  const handleModeChange = (mode) => {
    setPlcTags((prev) => ({ ...prev, Operating_Mode: mode }));
    setIoStatus((prev) => ({
      ...prev,
      InAutoOn: mode === 'AUTO',
      Manual: mode === 'MANUAL',
      InCycle: mode === 'AUTO' || mode === 'START',
    }));
  };

  const handleAlarmMute = () => {
    setPlcTags((prev) => ({ ...prev, Alarm_Muted: !prev.Alarm_Muted }));
  };

  const handleResetAll = () => {
    setAlarms((prev) => prev.map((a) => ({ ...a, active: false })));
  };

  const toggleCollisionZone = (id) => {
    setCollisionZones((prev) =>
      prev.map((z) => (z.id === id ? { ...z, active: !z.active } : z))
    );
  };

  const toggleSegment = (id, field) => {
    setSegments((prev) =>
      prev.map((s) => (s.id === id ? { ...s, [field]: !s[field] } : s))
    );
  };

  const activeAlarmBanner = alarms.find((a) => a.active && a.type === 'HIGH');

  return (
    <div className="flex flex-col h-screen bg-[#C0C0C0] font-sans select-none text-black overflow-hidden border-4 border-[#005B9E]">
      {/* ================= HEADER BAR ================= */}
      <header className="bg-[#007AA6] text-white flex items-center justify-between px-2 py-1 shadow-md border-b-2 border-gray-400">
        {/* Top Operational Controls */}
        <div className="flex items-center space-x-1">
          <button
            onClick={handlePowerToggle}
            className={`px-4 py-1.5 font-bold text-sm uppercase rounded-sm border-2 shadow-inner transition ${
              plcTags.Power_ON
                ? 'bg-amber-400 text-black border-amber-600 hover:bg-amber-300'
                : 'bg-gray-600 text-white border-gray-700'
            }`}
          >
            ON/OFF
          </button>
          <button
            onClick={() => handleModeChange('START')}
            className={`px-4 py-1.5 font-bold text-sm uppercase rounded-sm border-2 shadow ${
              plcTags.Operating_Mode === 'START'
                ? 'bg-green-600 border-white text-white'
                : 'bg-[#0080A0] hover:bg-[#0090B0] border-cyan-300 text-white'
            }`}
          >
            START
          </button>
          <button
            onClick={() => handleModeChange('AUTO')}
            className={`px-4 py-1.5 font-bold text-sm uppercase rounded-sm border-2 shadow ${
              plcTags.Operating_Mode === 'AUTO'
                ? 'bg-green-600 border-white text-white ring-2 ring-yellow-300'
