import React, { useState, useEffect } from 'react';

/**
 * JSW Production - Station Data Overview
 * Principal Frontend Engineering Implementation
 * Standard: Meta/Apple/Amazon/Microsoft Industrial UI
 */

const JSW_COLORS = {
  primary: '#0082A9',
  bg: '#C0C0C0',
  header: '#004B63',
  alarm: '#FFFF00',
  danger: '#CD5C5C',
  active: '#FFD700',
  text: '#000000',
  white: '#FFFFFF',
};

const STATIONS = [
  { id: 'MB110', name: 'MB110' },
  { id: 'MB120', name: 'MB120' },
  { id: 'MB130', name: 'MB130' },
  { id: '140APCLH_U', name: '140APCLH Unloading' },
  { id: '140APCLH_L', name: 'MB140APCLH Loading' },
  { id: '140APCRH_U', name: 'MB140APCRH Unloading' },
  { id: '140APCRH_L', name: 'MB140APCRH Loading' },
  { id: 'MB140RB03', name: 'MB140RB03' },
  { id: 'MB140RB04', name: 'MB140RB04' },
  { id: 'MB140', name: 'MB140' },
];

const DATA_LABELS = [
  "Station", "Seq No.", "BIW No.", "VIN No.", "Variant", 
  "Sub-Variant", "Body State", "Take Out Location", 
  "Take out Reason", "Skid No."
];

export default function GeneratedScreen() {
  // --- PLC TAG STATE ---
  const [plcTags, setPlcTags] = useState({
    System_Time: new Date().toLocaleString(),
    Line_Running: true,
    Operating_Mode: 'AUTO', // 'AUTO' | 'MANUAL'
    Active_Alarm: 'LineHighAlarm.Astop_140LHLC1 : 140LHLoadLC1_Grating fault',
    Alarm_Muted: false,
    Station_Status: Array.from({ length: 24 }, (_, i) => ({
      id: i + 1,
      state: i < 3 ? 'fault' : i < 9 ? 'active' : 'idle'
    }))
  });

  const [activeTab, setActiveTab] = useState('ProdData');

  // Update clock
  useEffect(() => {
    const timer = setInterval(() => {
      setPlcTags(prev => ({ ...prev, System_Time: new Date().toLocaleString() }));
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  // --- HANDLERS ---
  const toggleMode = (mode) => setPlcTags(prev => ({ ...prev, Operating_Mode: mode }));
  const togglePower = () => setPlcTags(prev => ({ ...prev, Line_Running: !prev.Line_Running }));
  const muteAlarm = () => setPlcTags(prev => ({ ...prev, Alarm_Muted: true }));
  const resetAll = () => setPlcTags(prev => ({ ...prev, Alarm_Muted: false, Active_Alarm: '' }));

  // --- COMPONENTS ---

  const ControlButton = ({ label, active, onClick, colorClass = "bg-[#0082A9]" }) => (
    <button
      onClick={onClick}
      className={`h-12 px-4 text-white font-bold text-sm border-r border-black/20 shadow-inner transition-all active:scale-95 flex items-center justify-center
        ${active ? 'bg-[#FFD700] text-black' : colorClass}
        ${label === 'RESET All' ? 'bg-[#CD5C5C]' : ''}
      `}
    >
      {label}
    </button>
  );

  const SidebarItem = ({ label }) => (
    <button
      onClick={() => setActiveTab(label)}
      className={`w-full py-3 px-2 text-white font-bold text-xs border-b border-white/10 text-center transition-colors
        ${activeTab === label ? 'bg-[#004B63] border-l-4 border-yellow-400' : 'hover:bg-[#006d8d]'}
      `}
    >
      {label}
    </button>
  );

  const StationCard = ({ station }) => (
    <div className="flex flex-col min-w-[180px] bg-white border border-gray-400 shadow-sm">
      <div className="bg-[#0082A9] text-white text-[10px] font-bold py-1 px-2 text-center truncate">
        {station.name}
      </div>
      <div className="flex flex-row divide-x divide-gray-300">
        {/* Two columns per station as seen in screenshot */}
        {[0, 1].map(col => (
          <div key={col} className="flex-1 flex flex-col text-[9px]">
            <div className="h-6 border-b flex items-center justify-center bg-gray-50">0</div>
            <div className="h-6 border-b flex items-center justify-center">0</div>
            <div className="h-6 border-b flex items-center justify-center bg-gray-50">-</div>
            <div className="h-6 border-b flex items-center justify-center text-[8px] text-gray-500">Select Variant</div>
            <div className="h-6 border-b flex items-center justify-center text-[8px] text-gray-500">Select Sub-Variant</div>
            <div className="h-6 border-b flex items-center justify-center text-green-600 font-semibold">Normal/Ok</div>
            <div className="h-6 border-b flex items-center justify-center text-gray-400">No Action</div>
            <div className="h-6 border-b flex items-center justify-center text-gray-400">No Action</div>
            <div className="h-6 border-b flex items-center justify-center">0</div>
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div className="flex flex-col h-screen w-full overflow-hidden font-sans select-none" style={{ backgroundColor: JSW_COLORS.bg }}>

      {/* TOP CONTROL BAR */}
      <div className="flex h-14 bg-[#0082A9] items-stretch border-b border-black/40">
        <ControlButton label="ON/OFF" active={plcTags.Line_Running} onClick={togglePower} />
        <ControlButton label="START" onClick={() => {}} />
        <ControlButton label="AUTO" active={plcTags.Operating_Mode === 'AUTO'} onClick={() => toggleMode('AUTO')} />
        <ControlButton label="MANUAL" active={plcTags.Operating_Mode === 'MANUAL'} onClick={() => toggleMode('MANUAL')} />

        {/* Station Grid 1-24 */}
        <div className="grid grid-cols-8 grid-rows-3 gap-[1px] bg-black/20 p-[2px] mx-2">
          {plcTags.Station_Status.map(s => (
            <div 
