import React, { useState, useEffect } from 'react';

export default function GeneratedScreen() {
  const [tags, setTags] = useState({
    lineRunning: true,
    mode: 'AUTO',
    alarmActive: true,
    alarmText: 'LineHighAlarm.Astop.Astop_140LHLC1 : 140LHLoadLC1_Grating fault',
    timestamp: new Date().toLocaleString('en-GB'),
    stationData: [
      { id: 'MB110', seq: 124, vin: 'JSW-9982', state: 'Normal/Ok' },
      { id: 'MB120', seq: 123, vin: 'JSW-9981', state: 'Normal/Ok' },
      { id: 'MB130', seq: 122, vin: 'JSW-9980', state: 'Warning' },
      { id: '140APCLH1', seq: 121, vin: 'JSW-9979', state: 'Normal/Ok' },
      { id: 'MB140RB03', seq: 120, vin: 'JSW-9978', state: 'Normal/Ok' }
    ]
  });

  const [activeTab, setActiveTab] = useState('ProdData');
  const navItems = ['Type', 'Robot', 'SEW-Drives', 'Alarm', 'ProdData', 'Diagnostic', 'System', 'Style.View', 'Style.Write', 'RFID', 'Order Control', 'Zone1Type Overview', 'Zone2Type Overview'];

  useEffect(() => {
    const timer = setInterval(() => setTags(prev => ({ ...prev, timestamp: new Date().toLocaleString('en-GB') })), 1000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div className="min-h-screen bg-[#C0C0C0] text-black font-sans flex flex-col">
      {/* Top Header Bar */}
      <header className="bg-[#008299] text-white p-2 flex items-center gap-2 border-b-4 border-[#005A70]">
        <div className="flex gap-1">
          {['ON/OFF', 'START', 'AUTO', 'MANUAL'].map(btn => (
            <button key={btn} className="bg-[#005A70] hover:bg-[#004050] px-4 py-2 font-bold border border-white shadow-md">{btn}</button>
          ))}
        </div>
        <div className="flex-1 text-center font-bold text-xl">MB110-140 Control Bar</div>
        <div className="text-sm font-mono">{tags.timestamp}</div>
        <button className="bg-[#E35E5E] px-4 py-2 font-bold border border-white">Alarm Mute</button>
        <button className="bg-[#E35E5E] px-4 py-2 font-bold border border-white">RESET All</button>
        <button className="bg-[#005A70] px-4 py-2 font-bold border border-white">Special</button>
      </header>

      {/* Alarm Banner */}
      {tags.alarmActive && (
        <div className="bg-[#FFFF00] p-2 font-bold border-b border-black text-sm flex items-center">
          <span className="mr-2">⚠️</span> {tags.alarmText}
        </div>
      )}

      <div className="flex flex-1">
        {/* Main Content Area */}
        <main className="flex-1 p-4">
          <div className="bg-[#008299] text-white text-center py-2 mb-4 font-bold">Station data overview</div>

          <div className="grid grid-cols-5 gap-4">
            {tags.stationData.map((station) => (
              <div key={station.id} className="bg-white border-2 border-[#008299] shadow-lg">
                <div className="bg-[#008299] text-white text-center font-bold p-1">{station.id}</div>
                <div className="p-2 text-xs space-y-1">
                  <div className="flex justify-between border-b"><span>Seq No.</span><span>{station.seq}</span></div>
                  <div className="flex justify-between border-b"><span>VIN No.</span><span>{station.vin}</span></div>
                  <div className="flex justify-between border-b"><span>Body State</span><span className={station.state === 'Warning' ? 'text-red-600' : ''}>{station.state}</span></div>
                  <div className="mt-2">
                    <select className="w-full border text-[10px]"><option>Select Variant</option></select>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </main>

        {/* Right Sidebar Navigation */}
        <aside className="w-48 bg-[#008299] p-2 flex flex-col gap-1">
          {navItems.map(item => (
            <button 
              key={item} 
              onClick={() => setActiveTab(item)}
              className={`w-full py-3 text-white font-bold border border-[#005A70] ${activeTab === item ? 'bg-[#005A70]' : 'hover:bg-[#005A70]'}`}
            >
              {item}
            </button>
          ))}
        </aside>
      </div>
    </div>
  );
}

